import{_,o as e,c as n,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS G/H (Day 2) - RBD: Copy-on-read for clones in kernel RBD client","description":"","frontmatter":{"title":"CDS G/H (Day 2) - RBD: Copy-on-read for clones in kernel RBD client","date":"2014-06-26T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["Ceph","RBD","Kernel RBD Client","Copy","on","read","Clone"],"categories":["会议纪要","存储技术","Ceph 架构","分布式存储"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_2_-_RBD_-_Copy-on-read_for_clones_in_kernel_RBD_client.md","filePath":"posts/2014/CDS_G_H_Day_2_-_RBD_-_Copy-on-read_for_clones_in_kernel_RBD_client.md","lastUpdated":1780460162000}'),t={name:"posts/2014/CDS_G_H_Day_2_-_RBD_-_Copy-on-read_for_clones_in_kernel_RBD_client.md"};function i(r,o,s,a,D,c){return e(),n("div",null,[...o[0]||(o[0]=[l("<p>本次会议主要讨论了在内核RBD客户端中实现RBD克隆的复制和读取功能。Min介绍了其蓝图，提出使用Carbon读取邻居BD的算法，并使用escrow覆盖方法将数据写入克隆。与会人员就实现位置、配置方式、用户空间复制和读取功能、复杂性问题、同步与异步、RBD客户端稳定性、锁机制、数据传输、obj_i_eq和device_flags等议题进行了深入讨论。</p><p><strong>主要讨论点</strong>：</p><ol><li><strong>实现位置</strong>： Josh建议在处理RBD图像对象请求提交的功能中实现Carbon读取，这是启动最高级别操作的函数。</li><li><strong>配置方式</strong>： 讨论了是否在映射图像时添加选项，以及如何与现有选项机制兼容。</li><li><strong>用户空间复制和读取功能</strong>： Josh提到用户空间复制和读取功能的v2 pull request仍存在问题，需要进一步改进。</li><li><strong>复杂性问题</strong>： 讨论了在内核侧实现复杂条带化可能遇到的挑战，以及是否应先实现复制和读取功能。</li><li><strong>同步与异步</strong>： 讨论了在满足读取请求之前是否应先执行整个提升操作，以及是否应使用同步或异步方式。</li><li><strong>RBD客户端稳定性</strong>： 确认RBD客户端非常稳定，但Min提到liberty覆盖与窃取相关的错误问题。</li><li><strong>锁机制</strong>： 讨论了当多个客户端访问同一图像时如何避免冲突，以及如何处理锁定。</li><li><strong>数据传输</strong>： 讨论了rbd_image_object_callback如何将数据返回给bio和vfs。</li><li><strong>obj_i_eq和device_flags</strong>： 讨论了obj_i_eq和device_flags的作用，以及如何区分页面列表和bio列表。</li></ol><p><strong>决定事项</strong>：</p><ol><li>继续推进RBD克隆的复制和读取功能实现。</li><li>将技术问题发送至邮件列表和irc进行讨论。</li><li>在接下来的一个月或两个月内，加快复制和读取功能的开发。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Min将完善RBD克隆复制和读取功能的实现方案。</li><li>Josh和Elia将协助解决用户空间复制和读取功能的问题。</li><li>所有参会人员将积极参与邮件列表和irc讨论，共同推进RBD克隆功能的开发。</li></ol>",7)])])}const d=_(t,[["render",i]]);export{g as __pageData,d as default};
